/**
 * Stable seed entry point.
 *
 * Add or update seed modules inside prisma/seed/ as `<name>.seed.ts`.
 * Do not edit this file when adding seed modules.
 */
import 'dotenv/config';

import { serverEnv } from '@lib/config/server';
import { disconnectDb } from '@lib/db';
import { logger } from '@lib/logger';

import { runSeeds } from './seed/index';

async function main(): Promise<void> {
  if (serverEnv.NODE_ENV === 'production') {
    throw new Error('The seed adds sample data and does not run in production.');
  }

  await runSeeds();
}

main()
  .catch((error: unknown) => {
    logger.error('seed.failed', error, { module: 'seed' });
    process.exitCode = 1;
  })
  .finally(() => disconnectDb());
